<?php declare(strict_types=1);
try{$journalOriginal=$service->originalEventDetails($periodId,(int)$periodOriginalRevision,$periodOriginalSha);$journalEvent=$journalOriginal['event'];$journalReport=$journalOriginal['report'];if(!in_array($journalEvent['payload']['kind'],['created','opened','account','posted','closed'],true))throw new DomainException('Ursprünglichen Vorgang dieses Abschlusszeitraums nicht gefunden.',404);}
catch(DomainException$ex){if(!headers_sent())http_response_code(in_array($ex->getCode(),[403,404,422],true)?$ex->getCode():403);echo '<p role="alert">'.e($periodText($ex->getMessage())).'</p>';return;}
$journalPayload=$journalEvent['payload'];$journalData=$journalPayload['data'];$journalKind=$journalPayload['kind'];$journalMoney=static fn(int$n):string=>number_format($n/100,2,',','.').' €';$journalDate=static fn(string$d):string=>implode('.',array_reverse(explode('-',$d)));
$journalTitle=match($journalKind){'created'=>'Abschlusszeitraum angelegt','opened'=>'Anfangsbestände übernommen','account'=>'Buchungskonto ergänzt','posted'=>($journalData['entry']['reversal_of']??null)!==null?'Ursprüngliche Buchung storniert':'Zusätzliche Buchung gespeichert','closed'=>'Abschluss dieses Zeitraums bestätigt'};
$journalNote=match($journalKind){'created'=>$journalData['definition']['evidence'],'posted'=>$journalData['entry']['evidence'],'account'=>implode(', ',array_column($journalData['accounts'],'name')),default=>$journalData['evidence']};
$journalAt=(new DateTimeImmutable($journalPayload['at']))->setTimezone(new DateTimeZone('Europe/Berlin'))->format('d.m.Y H:i');$journalCurrent=null;try{$journalCurrent=$service->report($periodId);}catch(DomainException){/* Historical originals remain independently readable. */}
$journalCurrentUrl=url(['view'=>'finance','tab'=>'tax','balance'=>'1','periods'=>'1','period_id'=>$periodId]);
?>
