<?php $journalEntries=$journalKind==='posted'?[$journalData['entry']]:($journalKind==='opened'?[['date'=>$journalReport['period']['start'],'description'=>$periodText('Anfangsbestände übernommen'),'evidence'=>$journalData['evidence'],'lines'=>$journalData['opening']]]:[]);foreach($journalEntries as$journalEntry): ?><article><h2><?= e($journalDate($journalEntry['date']).' · '.$journalEntry['description']) ?></h2><p><?= e($journalEntry['evidence']) ?></p><?php foreach($journalEntry['lines']as$journalLine): ?><p><?= e($journalReport['accounts'][$journalLine['account']]['name']) ?> · <?= e($periodText('Soll')) ?> <?= e($journalMoney($journalLine['debit_cents'])) ?> · <?= e($periodText('Haben')) ?> <?= e($journalMoney($journalLine['credit_cents'])) ?><?= $journalLine['sphere']!==''?' · '.e($periodText(\Kulturhus\Verein\TaxCatalog::SPHERES[$journalLine['sphere']])):'' ?></p><?php endforeach ?>
<?php if(($journalEntry['reversal_of']??null)!==null):$journalReversed=$journalReport['entries'][$journalEntry['reversal_of']]; ?><section data-period-journal-reversed-source><h3><?= e($periodText('Buchung')) ?></h3><p><?= e($journalDate($journalReversed['date']).' · '.$journalReversed['description']) ?></p><p><?= e($journalReversed['evidence']) ?></p><?php foreach($journalReversed['lines']as$journalLine): ?><p><?= e($journalReport['accounts'][$journalLine['account']]['name']) ?> · <?= e($periodText('Soll')) ?> <?= e($journalMoney($journalLine['debit_cents'])) ?> · <?= e($periodText('Haben')) ?> <?= e($journalMoney($journalLine['credit_cents'])) ?></p><?php endforeach ?></section><?php endif ?></article><?php endforeach ?>
<?php if($journalKind==='closed'): ?><dl><?php foreach(['complete'=>'Vollständigkeit der Belege','valuation'=>'Bewertung von Vermögen und Schulden','cutoff'=>'Zuordnung zum Abschlusszeitraum','tax'=>'Steuerliche Zuordnung']as$journalCheck=>$journalLabel): ?><dt><?= e($periodText($journalLabel)) ?></dt><dd><?= e($periodText($journalData['checks'][$journalCheck]?'Im ursprünglichen Formular bestätigt':'Im ursprünglichen Formular nicht bestätigt')) ?></dd><?php endforeach ?></dl><?php endif ?>
